function render() {
  timeDisplay.textContent = fmt(remaining);
  sessionLabel.textContent = { focus:'Focus', short:'Short break', long:'Long break' }[mode];
  const frac = 1 - (remaining / (S.settings[mode] * 60));
  ringFg.style.strokeDashoffset = String(CIRC * (1 - frac));
  timerPanel.classList.remove('mode-focus','mode-short','mode-long');
  timerPanel.classList.add('mode-' + mode);
  document.title = (running ? '▶ ' : '') + fmt(remaining) + ' · ' + (sessionLabel.textContent) + ' — Ember';
  renderPips();
}
function renderPips() {
  const wrap = document.getElementById('pipsWrap');
  wrap.innerHTML = '';
  for (let i = 0; i < S.settings.goal; i++) {
    const d = document.createElement('span');
    d.className = 'pip' + (i < focusCountInCycle ? ' done' : '');
    wrap.appendChild(d);
  }
}
function setMode(m) {
  mode = m;
