function completeSession() {
  const finished = mode;          // capture before switching
  stopTimer();
  chime();
  if (finished === 'focus') {
    focusCountInCycle = Math.min(focusCountInCycle + 1, S.settings.goal);
    recordSession();
    setMode(focusCountInCycle >= S.settings.goal ? 'long' : 'short');
  } else {
    // a break finished → back to focus; long break finishes the cycle
    if (finished === 'long') focusCountInCycle = 0;
    setMode('focus');
  }
  flashTitle();
  renderStats();
  persist();
}
