/* ---------- week bar chart (last 7 days) ---------- */
const weekOffsets = [0, -1]; // 0=this week, -1=last week; labels Mon-Sun
function renderWeekBars(byDay, offsetIdx) {
  const DAYS = 7;
  const w = 600, h = 150, padL = 30, padB = 22, padT = 12;
  const maxCount = Math.max(1, ...days.map(d=>byDay[dateKey(d)]||0));
  const sunday = new Date(); sunday.setDate(sunday.getDate() - sunday.getDay());
  sunday.setDate(sunday.getDate() - offsetIdx*7);
  const monday = new Date(sunday); monday.setDate(sunday.getDate()-6); // sun back 6 → mon

  // build 7 days Mon..Sun
  const days = [];
  for (let i=0;i<7;i++){ const d=new Date(monday); d.setDate(d.getDate()+i); days.push(d); }
  const total = days.reduce((a,d)=>a+(byDay[dateKey(d)]||0),0);
  document.getElementById('weekTotal').textContent = total + ' sessions · ' + (total>=S.settings.goal*7 ? 'on a roll' : '');

