const { JSDOM } = require('jsdom');
const fs = require('fs');
const html = fs.readFileSync('/workspace/index.html','utf8');
const dom = new JSDOM(html, {
  url: 'http://localhost/',
  runScripts: 'dangerously',
  pretendToBeVisual: true,
  beforeParse(window) {
    // Web Audio not available in jsdom; stub minimally so script doesn't crash at define time
    window.AudioContext = class { constructor(){ this.state='running'; this.destination={}; this.currentTime=0; this.sampleRate=44100;
      this.createGain=()=>({gain:{value:0,setValueAtTime(){},cancelScheduledValues(){},setTargetAtTime(){},linearRampToValueAtTime(){},exponentialRampToValueAtTime(){}},connect(){return this;}});
      this.createBufferSource=()=>({connect(){return this;},start(){},stop(){},buffer:null,loop:true});
      this.createBuffer=()=>({getChannelData(){return new Float32Array(44100);}});
      this.createBiquadFilter=()=>({type:'',frequency:{value:0},Q:{value:0},connect(){return this;}});
      this.createOscillator=()=>({type:'',frequency:{value:0,setValueAtTime(){}},connect(){return this;},start(){},stop(){}});
      this.resume=()=>Promise.resolve();
    } };
    // rAF polyfill via pretendToBeVisual
    window.requestAnimationFrame = (cb)=>setTimeout(()=>cb(Date.now()),16);
    window.cancelAnimationFrame = (id)=>clearTimeout(id);
  }
});
const { window } = dom;
setTimeout(()=>{
  try {
    const doc = window.document;
    // initial state
    console.log('timeDisplay shows:', doc.getElementById('timeDisplay').textContent);
    console.log('startBtn text:', doc.getElementById('startBtn').textContent);
    console.log('pips count:', doc.querySelectorAll('.pip').length);
    console.log('sound cards:', doc.querySelectorAll('.sound-card').length);
    console.log('statTotal:', doc.getElementById('statTotal').textContent);
    // simulate a completed focus session via keyboard 'm' mode cycling etc.
    // hit start
    doc.getElementById('startBtn').click();
    console.log('after start, btn:', doc.getElementById('startBtn').textContent);
    // no session recorded yet
    console.log('sessions stored:', JSON.parse(localStorage.getItem('ember.focus.v1')||'{}').sessions ? 'present' : 'none');
    console.log('heatmap cells:', doc.querySelectorAll('.heat-cell').length);
    console.log('bar rects:', doc.querySelectorAll('.bar-rect').length);
    console.log('week selector buttons:', doc.querySelectorAll('#weekSelector button').length);
    // stats toggle off/on
    doc.getElementById('statsToggleBtn').click();
    console.log('stats hidden after toggle:', doc.getElementById('statsPanel').classList.contains('hidden'));
    window.close();
  } catch(e){ console.error('RUNTIME ERROR:', e); process.exit(1); }
}, 300);
