let html = `<svg viewBox="0 0 ${w} ${h}" width="100%" role="img" aria-label="Bar chart of focus sessions for the last 7 days" style="overflow:visible">`;
// gridlines
const n = 4;
for (let i=0;i<=n;i++){
  const y = padT + (h-padT-padB) * i/n;
  html += `<line x1="${padL}" x2="${w-10}" y1="${y}" y2="${y}" stroke="var(--grid)" stroke-width="1"/>`;
  html += `<text x="${padL-6}" y="${y+4}" text-anchor="end" fill="var(--ink-3)" font-size="10">${Math.round(maxCount*(n-i)/n)}</text>`;
}
const bw = ((w-10-padL) / DAYS) * 0.6;
days.forEach((d,i)=>{
  const count = byDay[dateKey(d)]||0;
  const cx = padL + ((w-10-padL)/DAYS)*i + ((w-10-padL)/DAYS)/2;
  const bh = (count/maxCount)*(h-padT-padB);
  const y = padT + (h-padT-padB) - bh;
  const isToday = dateKey(d)===todayKey();
  const label = d.toLocaleDateString(undefined,{weekday:'narrow'});
  html += `<rect class="bar-rect" data-k="${dateKey(d)}" data-c="${count}" x="${cx-bw/2}" y="${y}" width="${bw}" height="${Math.max(bh,2)}" rx="5" fill="${isToday?'url(#7dayGrad)':'#3987e5'}" opacity="${isToday?1:0.55}"/>`;
  html += `<text x="${cx}" y="${h-8}" text-anchor="middle" fill="var(--ink-3)" font-size="10">${label}</text>`;
});
// today gradient
html += `<defs><linearGradient id="7dayGrad" x1="0" y1="0" x2="0" y2="1">
  <stop offset="0%" stop-color="#6da7ec"/><stop offset="100%" stop-color="#3987e5"/>
  </linearGradient></defs>`;
html += '</svg>';
barEl.innerHTML = html;
barEl.querySelectorAll('.bar-rect').forEach(bar => {
  bar.addEventListener('mousemove', (e)=>{
    const c = bar.dataset.c;
    const name = new Date(bar.dataset.k+'T00:00:00').toLocaleDateString(undefined,{weekday:'long',month:'short',day:'numeric'});
    showTooltip(`<strong>${c}</strong> session${c==1?'':'s'} · ${name}`, e.clientX, e.clientY);

