input.command:
cd /tmp && node - <<'PY'
const { JSDOM } = require('jsdom');
const fs = require('fs');
const html = fs.readFileSync('/workspace/index.html','utf8');
const dom = new JSDOM(html, { url:'http://localhost/', runScripts:'dangerously' });
const doc = dom.window.document;
setTimeout(()=>{
  console.log('time:', doc.getElementById('timeDisplay').textContent);
  console.log('pips:', doc.querySelectorAll('.pip').length, '(goal 8)');
  console.log('heat cells:', doc.querySelectorAll('.heat-cell').length);
  console.log('bar rects:', doc.querySelectorAll('.bar-rect').length);
  console.log('sound cards:', doc.querySelectorAll('.sound-card').length);
  console.log('week buttons:', doc.querySelectorAll('#weekSelector button').length);
  console.log('NO RUNTIME ERRORS');
  dom.window.close(); process.exit(0);
}, 300);
